// Mock credential registry - swap for Okta IdP cert API, your vault's API, or a Sheet the team maintains
const now = Date.now(); const days = d => new Date(now + d * 86400e3).toISOString();
return [
  { json: { name: 'Okta SAML signing cert (Workday app)', type: 'saml-cert', system: 'Okta > Workday', owner: 'it-ops', expiresAt: days(5) } },
  { json: { name: 'Jamf API integration token', type: 'api-token', system: 'Jamf', owner: 'it-ops', expiresAt: days(12) } },
  { json: { name: 'wildcard TLS cert *.internal.example.com', type: 'tls-cert', system: 'Internal services', owner: 'infra', expiresAt: days(25) } },
  { json: { name: 'Slack app signing secret rotation', type: 'integration-secret', system: 'Slack', owner: 'it-ops', expiresAt: days(200) } }
];

// Alert tiers: 30 days = notice, 14 = warning, 7 = critical. Before expiry, never after.
const out = [];
for (const item of $input.all()) {
  const c = item.json;
  const daysLeft = Math.floor((new Date(c.expiresAt).getTime() - Date.now()) / 86400e3);
  let tier = null;
  if (daysLeft <= 7) tier = 'CRITICAL';
  else if (daysLeft <= 14) tier = 'WARNING';
  else if (daysLeft <= 30) tier = 'NOTICE';
  if (tier) out.push({ json: { ...c, daysLeft, tier } });
}
out.sort((a, b) => a.json.daysLeft - b.json.daysLeft);
if (!out.length) return [];
const lines = out.map(({ json: c }) => '[' + c.tier + '] ' + c.name + '\n  system: ' + c.system + ' | owner: ' + c.owner + ' | expires in ' + c.daysLeft + ' day(s)');
return [{ json: {
  subject: 'Expiry sentinel: ' + out.length + ' credential(s) inside 30 days',
  body: 'Pre-expiry sweep (30/14/7 day tiers):\n\n' + lines.join('\n\n') + '\n\nRotate now, not the night it breaks. This failure class caused a production outage exactly once; pre-expiry alerting is why it never did again.'
} }];
